const {spawnSync} = require('child_process');
const BIN='/workspace/dataset/test4_executable';
function run(val){
  const r = spawnSync(BIN, ['--a', val], {encoding:'buffer', maxBuffer:1<<28});
  return {code:r.status, signal:r.signal, out:r.stdout, err:r.stderr, error:r.error?String(r.error):null};
}
module.exports={run};
if(require.main===module){
  // cases fed via JSON on argv[2]: array of {label, hex}
  const cases=JSON.parse(process.argv[2]);
  for(const c of cases){
    const buf = c.hex!==undefined ? Buffer.from(c.hex,'hex') : Buffer.from(c.str,'utf8');
    const val = buf.toString('utf8'); // may mangle invalid utf8; use hexArg mode instead
    const r=run(val);
    console.log(JSON.stringify({label:c.label, inHex:buf.toString('hex').slice(0,200), inLen:buf.length,
      code:r.code, signal:r.signal, outHex:r.out?r.out.toString('hex').slice(0,400):null,
      outLen:r.out?r.out.length:0,
      errText:r.err?r.err.toString('utf8').slice(0,300):'', error:r.error}));
  }
}
